files.content:
body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 850px;
  min-height: 100vh;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 24px;
  background-color: #ffc802;
}

div {
  box-shadow: 24px 24px 0 tomato;
  display: flex;
  align-items: center;
  box-sizing: border-box;
  width: 500px;
  height: 300px;
  margin-top: 40px;
  margin-left: 20px;
  border: 4px solid #5f0dee;
  padding: 40px;
  background-color: white;
}
